<ref name = "whybiotech.com">{{cite web |url=http://foodsafety.ksu.edu/articles/497/Substantial_Equivalence.pdf | archive-url = https://web.archive.org/web/20090206170413/http://foodsafety.ksu.edu/articles/497/Substantial_Equivalence.pdf |title=Substantial Equivalence in Food Safety Assessment |work=Council for Biotechnology Information |date=11 March 2001 | archive-date = 6 February 2009 }}</ref>
<ref name = "AMA">{{cite web |publisher=American Medical Association |date=2012 |url=http://www.ama-assn.org/resources/doc/csaph/a12-csaph2-bioengineeredfoods.pdf | archive-url = https://web.archive.org/web/20120907023039/http://www.ama-assn.org/resources/doc/csaph/a12-csaph2-bioengineeredfoods.pdf | archive-date = 7 September 2012  |title=Report 2 of the Council on Science and Public Health: Labeling of Bioengineered Foods |quote=Bioengineered foods have been consumed for close to 20 years, and during that time, no overt consequences on human health have been reported and/or substantiated in the peer-reviewed literature. (first page)}}</ref>
<ref name = "AMA_2012">{{cite web |publisher=[[American Medical Association]] |date=2012 |url=http://www.ama-assn.org/resources/doc/csaph/a12-csaph2-bioengineeredfoods.pdf |title=Report 2 of the Council on Science and Public Health: Labeling of Bioengineered Foods. |quote=To better detect potential harms of bioengineered foods, the Council believes that pre-market safety assessment should shift from a voluntary notification process to a mandatory requirement |page=7 |access-date=November 7, 2012 |archive-date=September 7, 2012 |archive-url=https://web.archive.org/web/20120907023039/http://www.ama-assn.org/resources/doc/csaph/a12-csaph2-bioengineeredfoods.pdf }}</ref>
